-- Fase 4.4. Ejecutar como propietario en Supabase SQL Editor.
-- PRECAUCIÓN: realizar backup antes de migrar. No sustituye políticas RLS de datos de negocio.
BEGIN;
CREATE TABLE IF NOT EXISTS public.rbac_roles (codigo text PRIMARY KEY, nombre text NOT NULL, descripcion text NOT NULL DEFAULT '', activo boolean NOT NULL DEFAULT true, protegido boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.rbac_permisos (codigo text PRIMARY KEY, nombre text NOT NULL, modulo text NOT NULL);
CREATE TABLE IF NOT EXISTS public.rbac_rol_permisos (rol_codigo text NOT NULL REFERENCES public.rbac_roles(codigo) ON DELETE CASCADE, permiso_codigo text NOT NULL REFERENCES public.rbac_permisos(codigo) ON DELETE CASCADE, PRIMARY KEY(rol_codigo,permiso_codigo));
ALTER TABLE public.rbac_roles ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rbac_permisos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.rbac_rol_permisos ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.rbac_roles,public.rbac_permisos,public.rbac_rol_permisos FROM PUBLIC,anon,authenticated;
-- Bloquear modificación directa: exclusivamente RPC SECURITY DEFINER autorizada.

-- Compatibilidad con códigos legados sin tocar perfiles existentes.
CREATE OR REPLACE FUNCTION public.rbac_normalizar_codigo(p text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT CASE lower(trim(p)) WHEN 'administrador' THEN 'admin' WHEN 'gerente' THEN 'gerente_rh' ELSE lower(trim(p)) END $$;
CREATE OR REPLACE FUNCTION public.rbac_es_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE (p.id=auth.uid() OR p.auth_id=auth.uid()) AND public.rbac_normalizar_codigo(p.role_code)='admin' AND p.activo IS DISTINCT FROM false) $$;
CREATE OR REPLACE FUNCTION public.rbac_mis_permisos() RETURNS TABLE(permiso text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT rp.permiso_codigo FROM public.profiles p JOIN public.rbac_roles r ON r.codigo=public.rbac_normalizar_codigo(p.role_code) JOIN public.rbac_rol_permisos rp ON rp.rol_codigo=r.codigo WHERE (p.id=auth.uid() OR p.auth_id=auth.uid()) AND p.activo IS DISTINCT FROM false AND r.activo=true;
$$;
CREATE OR REPLACE FUNCTION public.rbac_tiene_permiso(p_permiso text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.rbac_mis_permisos() m WHERE m.permiso=p_permiso) $$;
CREATE OR REPLACE FUNCTION public.rbac_listar_roles() RETURNS TABLE(codigo text,nombre text,descripcion text,activo boolean,protegido boolean,permisos text[]) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NOT public.rbac_tiene_permiso('ver_usuarios') AND NOT public.rbac_tiene_permiso('gestionar_roles') THEN RAISE EXCEPTION 'Acceso denegado'; END IF;
 RETURN QUERY SELECT r.codigo,r.nombre,r.descripcion,r.activo,r.protegido,coalesce(array_agg(rp.permiso_codigo ORDER BY rp.permiso_codigo) FILTER(WHERE rp.permiso_codigo IS NOT NULL),ARRAY[]::text[]) FROM public.rbac_roles r LEFT JOIN public.rbac_rol_permisos rp ON rp.rol_codigo=r.codigo GROUP BY r.codigo,r.nombre,r.descripcion,r.activo,r.protegido ORDER BY r.nombre;
END $$;
CREATE OR REPLACE FUNCTION public.rbac_catalogo_permisos() RETURNS TABLE(codigo text,nombre text,modulo text) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$ BEGIN
 IF NOT public.rbac_tiene_permiso('gestionar_roles') THEN RAISE EXCEPTION 'Acceso denegado'; END IF;
 RETURN QUERY SELECT p.codigo,p.nombre,p.modulo FROM public.rbac_permisos p ORDER BY p.modulo,p.nombre;
END $$;
CREATE OR REPLACE FUNCTION public.rbac_guardar_rol(p_codigo text,p_nombre text,p_descripcion text,p_activo boolean,p_permisos text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE v_codigo text:=lower(trim(p_codigo)); BEGIN
 IF NOT public.rbac_es_admin() OR NOT public.rbac_tiene_permiso('gestionar_roles') THEN RAISE EXCEPTION 'Solo Administrador puede gestionar roles'; END IF;
 IF v_codigo !~ '^[a-z][a-z0-9_]{2,49}$' OR length(trim(p_nombre))<3 THEN RAISE EXCEPTION 'Código o nombre inválido'; END IF;
 IF EXISTS(SELECT 1 FROM public.rbac_roles WHERE codigo=v_codigo AND protegido) THEN RAISE EXCEPTION 'Rol protegido: no se permite modificar'; END IF;
 IF p_permisos IS NULL OR EXISTS(SELECT 1 FROM unnest(p_permisos) x WHERE NOT EXISTS(SELECT 1 FROM public.rbac_permisos y WHERE y.codigo=x)) THEN RAISE EXCEPTION 'Permisos inválidos'; END IF;
 DELETE FROM public.rbac_rol_permisos WHERE rol_codigo=v_codigo;
END $$;
-- El Administrador protegido conserva todos los permisos registrados, incluidos los nuevos.
REVOKE ALL ON FUNCTION public.rbac_es_admin(),public.rbac_normalizar_codigo(text),public.rbac_mis_permisos(),public.rbac_tiene_permiso(text),public.rbac_listar_roles(),public.rbac_catalogo_permisos(),public.rbac_guardar_rol(text,text,text,boolean,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.rbac_mis_permisos(),public.rbac_tiene_permiso(text),public.rbac_listar_roles(),public.rbac_catalogo_permisos(),public.rbac_guardar_rol(text,text,text,boolean,text[]) TO authenticated;
COMMIT;
